"""Synthetic exFAT filesystem image generator for forensic testing."""

import hashlib
import struct
from dataclasses import dataclass, field
from pathlib import Path

from recoverx.domain.enums import FileSystemType
from recoverx.filesystems.exfat.entry import exfat_entry_set_checksum
from recoverx.filesystems.exfat.vbr import calculate_exfat_vbr_checksum


@dataclass(slots=True)
class ExpectedExFatFile:
    """Expected file metadata recorded in synthetic exFAT image manifest."""

    filename: str
    relative_path: str
    content: bytes
    sha256_hash: str
    is_deleted: bool
    is_overwritten: bool
    no_fat_chain: bool
    corrupt_checksum: bool
    first_cluster: int
    size_bytes: int


@dataclass(slots=True)
class SyntheticExFatManifest:
    """Manifest describing files and filesystem geometry generated by SyntheticExFatBuilder."""

    image_path: Path
    filesystem_type: FileSystemType
    total_size_bytes: int
    cluster_size_bytes: int
    files: list[ExpectedExFatFile] = field(default_factory=list)

    def get_file(self, filename: str) -> ExpectedExFatFile | None:
        """Find an expected file by filename."""
        for f in self.files:
            if f.filename == filename:
                return f
        return None


class SyntheticExFatBuilder:
    """Constructs valid exFAT disk images with known files, entry sets, and allocation states."""

    def __init__(
        self,
        volume_label: str = "EXFAT_TEST",
        bytes_per_sector: int = 512,
        sectors_per_cluster: int = 8,  # 4096 byte clusters
        total_sectors: int = 32768,  # 16 MiB image
    ) -> None:
        self.volume_label = volume_label
        self.bytes_per_sec = bytes_per_sector
        self.sec_per_clus = sectors_per_cluster
        self.total_sectors = total_sectors
        self._files_to_add: list[tuple[str, str, bytes, bool, bool, bool, bool]] = []
        # (filename, subpath, content, is_deleted, is_overwritten, no_fat_chain, corrupt_checksum)

    def add_file(
        self,
        filename: str,
        content: bytes,
        subpath: str = "",
        is_deleted: bool = False,
        is_overwritten: bool = False,
        no_fat_chain: bool = True,
        corrupt_checksum: bool = False,
    ) -> "SyntheticExFatBuilder":
        """Queue a file for inclusion in the generated exFAT image."""
        self._files_to_add.append(
            (filename, subpath, content, is_deleted, is_overwritten, no_fat_chain, corrupt_checksum)
        )
        return self

    def build(self, output_path: Path) -> SyntheticExFatManifest:
        """Assemble the complete exFAT disk image and write to output_path."""
        output_path.parent.mkdir(parents=True, exist_ok=True)

        bps = self.bytes_per_sec
        spc = self.sec_per_clus
        cluster_size = bps * spc
        total_size = self.total_sectors * bps

        image = bytearray(total_size)

        # Geometry calculations
        sec_shift = 9 if bps == 512 else 12
        clus_shift = 0
        temp_spc = spc
        while temp_spc > 1:
            clus_shift += 1
            temp_spc >>= 1

        fat_offset = 24  # Sectors 0..23 reserved for Main & Backup VBR
        # Calculate cluster count
        heap_offset = 128  # Cluster heap starts at sector 128
        cluster_count = (self.total_sectors - heap_offset) // spc
        fat_length = ((cluster_count + 2) * 4 + bps - 1) // bps

        root_clus = 2
        bitmap_clus = 3
        upcase_clus = 4
        next_free_clus = 5

        # 1. Build Sector 0 (Boot Sector)
        boot_sector = bytearray(bps)
        boot_sector[0:3] = b"\xeb\x76\x90"
        boot_sector[3:11] = b"EXFAT   "
        struct.pack_into("<Q", boot_sector, 64, 0)  # PartitionOffset
        struct.pack_into("<Q", boot_sector, 72, self.total_sectors)  # VolumeLength
        struct.pack_into("<I", boot_sector, 80, fat_offset)
        struct.pack_into("<I", boot_sector, 84, fat_length)
        struct.pack_into("<I", boot_sector, 88, heap_offset)
        struct.pack_into("<I", boot_sector, 92, cluster_count)
        struct.pack_into("<I", boot_sector, 96, root_clus)
        struct.pack_into("<I", boot_sector, 100, 0x12345678)  # VolumeSerialNumber
        struct.pack_into("<H", boot_sector, 104, 0x0100)  # FSRevision 1.00
        struct.pack_into("<H", boot_sector, 106, 0)  # VolumeFlags
        boot_sector[108] = sec_shift
        boot_sector[109] = clus_shift
        boot_sector[110] = 1  # NumberOfFats
        boot_sector[111] = 0x80  # DriveSelect
        boot_sector[112] = 0  # PercentInUse
        boot_sector[510:512] = b"\x55\xaa"

        # 2. Assemble Main Boot Region (Sectors 0..11)
        vbr_main = bytearray(12 * bps)
        vbr_main[0:bps] = boot_sector
        # Sectors 1..8 zeroed, Sector 9 OEM params (zeroed), Sector 10 reserved
        # Calculate VBR checksum across sectors 0..10
        vbr_checksum = calculate_exfat_vbr_checksum(bytes(vbr_main[0 : 11 * bps]), bps)
        # Sector 11: Repeat 32-bit checksum pattern across entire sector
        sec11_data = bytearray(bps)
        for i in range(0, bps, 4):
            struct.pack_into("<I", sec11_data, i, vbr_checksum)
        vbr_main[11 * bps : 12 * bps] = sec11_data

        # Copy Main Boot Region (sectors 0..11) and Backup Boot Region (sectors 12..23)
        image[0 : 12 * bps] = vbr_main
        image[12 * bps : 24 * bps] = vbr_main

        # 3. Allocation Bitmap Initialization
        bitmap_bytes_len = (cluster_count + 7) // 8
        bitmap_bytes = bytearray(bitmap_bytes_len)

        def set_bitmap_bit(clus_num: int, is_alloc: bool) -> None:
            bit_idx = clus_num - 2
            byte_idx = bit_idx // 8
            bit_off = bit_idx % 8
            if is_alloc:
                bitmap_bytes[byte_idx] |= 1 << bit_off
            else:
                bitmap_bytes[byte_idx] &= ~(1 << bit_off)

        # Mark system clusters as allocated: Root (2), Bitmap (3), Upcase (4)
        set_bitmap_bit(root_clus, True)
        set_bitmap_bit(bitmap_clus, True)
        set_bitmap_bit(upcase_clus, True)

        # 4. Allocate and Write Files
        def cluster_to_offset(c: int) -> int:
            return (heap_offset + ((c - 2) * spc)) * bps

        root_entries: bytearray = bytearray()
        manifest_files: list[ExpectedExFatFile] = []

        # Root Special Entry 1: Allocation Bitmap (0x81)
        bmp_entry = bytearray(32)
        bmp_entry[0] = 0x81
        bmp_entry[1] = 0x00  # BitmapFlags (first FAT bitmap)
        struct.pack_into("<I", bmp_entry, 20, bitmap_clus)
        struct.pack_into("<Q", bmp_entry, 24, bitmap_bytes_len)
        root_entries.extend(bmp_entry)

        # Root Special Entry 2: Up-case Table (0x82)
        upcase_entry = bytearray(32)
        upcase_entry[0] = 0x82
        struct.pack_into("<I", upcase_entry, 4, 0x12345678)  # TableChecksum
        struct.pack_into("<I", upcase_entry, 20, upcase_clus)
        struct.pack_into("<Q", upcase_entry, 24, 512)
        root_entries.extend(upcase_entry)

        # Root Special Entry 3: Volume Label (0x83)
        if self.volume_label:
            vlabel_entry = bytearray(32)
            vlabel_entry[0] = 0x83
            label_chars = self.volume_label[:11]
            vlabel_entry[1] = len(label_chars)
            vlabel_bytes = label_chars.encode("utf-16-le")
            vlabel_entry[2 : 2 + len(vlabel_bytes)] = vlabel_bytes
            root_entries.extend(vlabel_entry)

        for (
            filename,
            subpath,
            content,
            is_del,
            is_overwritten,
            no_fat_chain,
            corrupt_chk,
        ) in self._files_to_add:
            content_size = len(content)
            clusters_needed = (
                (content_size + cluster_size - 1) // cluster_size if content_size > 0 else 0
            )

            file_first_cluster = next_free_clus if clusters_needed > 0 else 0

            # Write file payload into data clusters
            if clusters_needed > 0:
                for idx in range(clusters_needed):
                    clus = file_first_cluster + idx
                    clus_off = cluster_to_offset(clus)
                    chunk_start = idx * cluster_size
                    chunk = content[chunk_start : chunk_start + cluster_size]
                    image[clus_off : clus_off + len(chunk)] = chunk

                    # Set allocation bitmap bit
                    if not is_del:
                        set_bitmap_bit(clus, True)
                    elif is_overwritten:
                        # Overwritten file has cluster marked allocated in bitmap!
                        set_bitmap_bit(clus, True)
                    else:
                        # Deleted file has cluster cleared to 0 (free) in bitmap!
                        set_bitmap_bit(clus, False)

                next_free_clus += clusters_needed

            # Create File Directory Entry Set
            entry_set_bytes = self._create_file_entry_set(
                filename=filename,
                first_cluster=file_first_cluster,
                file_size=content_size,
                is_deleted=is_del,
                no_fat_chain=no_fat_chain,
                corrupt_checksum=corrupt_chk,
            )
            root_entries.extend(entry_set_bytes)

            manifest_files.append(
                ExpectedExFatFile(
                    filename=filename,
                    relative_path=filename if not subpath else f"{subpath}/{filename}",
                    content=content,
                    sha256_hash=hashlib.sha256(content).hexdigest(),
                    is_deleted=is_del,
                    is_overwritten=is_overwritten,
                    no_fat_chain=no_fat_chain,
                    corrupt_checksum=corrupt_chk,
                    first_cluster=file_first_cluster,
                    size_bytes=content_size,
                )
            )

        # Write root directory cluster into image
        root_off = cluster_to_offset(root_clus)
        image[root_off : root_off + len(root_entries)] = root_entries

        # Write Allocation Bitmap cluster into image
        bitmap_off = cluster_to_offset(bitmap_clus)
        image[bitmap_off : bitmap_off + len(bitmap_bytes)] = bitmap_bytes

        # Write image file to disk
        output_path.write_bytes(image)

        return SyntheticExFatManifest(
            image_path=output_path,
            filesystem_type=FileSystemType.EXFAT,
            total_size_bytes=total_size,
            cluster_size_bytes=cluster_size,
            files=manifest_files,
        )

    def _create_file_entry_set(
        self,
        filename: str,
        first_cluster: int,
        file_size: int,
        is_deleted: bool,
        no_fat_chain: bool,
        corrupt_checksum: bool,
    ) -> bytearray:
        """Construct an exFAT directory entry set (File, Stream Extension, and Name entries)."""
        # Calculate number of name entries (15 chars per entry)
        name_len = len(filename)
        name_entries_count = (name_len + 14) // 15
        secondary_count = 1 + name_entries_count  # 1 Stream Extension + N Name entries

        set_bytes = bytearray((1 + secondary_count) * 32)

        # 1. Primary File Directory Entry (Entry 0) - build as active first
        set_bytes[0] = 0x85
        set_bytes[1] = secondary_count
        struct.pack_into("<H", set_bytes, 4, 0x0020)  # FileAttributes: Archive
        ts_val = (46 << 25) | (10 << 21) | (28 << 16) | (14 << 11)
        struct.pack_into("<I", set_bytes, 8, ts_val)
        struct.pack_into("<I", set_bytes, 12, ts_val)

        # 2. Stream Extension Directory Entry (Entry 1)
        stream_off = 32
        set_bytes[stream_off] = 0xC0
        gen_flags = 0x01 | (0x02 if no_fat_chain else 0x00)  # AllocationPossible | NoFatChain
        set_bytes[stream_off + 1] = gen_flags
        set_bytes[stream_off + 3] = name_len
        struct.pack_into("<Q", set_bytes, stream_off + 8, file_size)  # ValidDataLength
        struct.pack_into("<I", set_bytes, stream_off + 20, first_cluster)
        struct.pack_into("<Q", set_bytes, stream_off + 24, file_size)  # DataLength

        # 3. File Name Directory Entries (Entries 2..N)
        for idx in range(name_entries_count):
            name_off = (2 + idx) * 32
            set_bytes[name_off] = 0xC1
            chunk = filename[idx * 15 : (idx + 1) * 15]
            chunk_bytes = chunk.encode("utf-16-le")
            set_bytes[name_off + 2 : name_off + 2 + len(chunk_bytes)] = chunk_bytes

        # Calculate and write SetChecksum at bytes 2-3 of Entry 0
        computed_chk = exfat_entry_set_checksum(bytes(set_bytes))
        if corrupt_checksum:
            computed_chk = (computed_chk + 1) & 0xFFFF
        struct.pack_into("<H", set_bytes, 2, computed_chk)

        # If deleted, OS clears active bit (0x80) on each entry's type byte
        if is_deleted:
            set_bytes[0] = 0x05
            set_bytes[stream_off] = 0x40
            for idx in range(name_entries_count):
                set_bytes[(2 + idx) * 32] = 0x41

        return set_bytes
